/* Optional local wizard. No files, messages or production API calls leave this page. */
(()=>{
 const $=id=>document.getElementById(id),esc=v=>AtlasViews.esc(v);let step=0,adjustmentText='',draftDirty=false,draftBase='';
 const principal=()=>{const id=window.AtlasCurrentChoice?.().selectedStyles[0]?.id;return id?window.AtlasApp.getStyle(id):null;};
 const briefKey=c=>JSON.stringify([c.topic,c.brand,c.format,c.targetDurationSeconds,c.guidedBrief]);
 const labels={one_photo:'Uma foto do produto',photos:'Várias fotos',video:'Vídeos',logo:'Logotipo',website:'Site',screens:'Capturas de telas',idea:'Somente uma ideia'};
 const value=()=>AtlasGuided.normalizeBrief({objective:$('guidedObjective').value,subject:$('guidedSubject').value,complexity:$('guidedComplexity').value,materials:[...document.querySelectorAll('#guidedMaterials input:checked')].map(x=>x.value)});
 function download(data,name){const url=URL.createObjectURL(new Blob([JSON.stringify(data,null,2)],{type:'application/json'}));const a=document.createElement('a');a.href=url;a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);}
 async function copy(text){try{await navigator.clipboard.writeText(text);return true}catch{$('projectMessage').textContent='Não foi possível copiar. Baixe o projeto ou copie o pedido pela tela de revisão.';return false;}}
 function suggestions(){
  const c=AtlasCurrentChoice(),s=principal(),items=AtlasGuided.recommend(AtlasApp.getCatalog().styles.filter(x=>x.id!==s?.id),value());
  const box=$('guidedCurrentStyle');box.hidden=!s;
  box.innerHTML=s?`<div class="guided-choice">${AtlasViews.picture(s,s.sequence.heroIndex??1,window.ATLAS_ASSET_BASE||'')}<div><p class="eyebrow">Seu estilo principal</p><strong>${esc(s.name)}</strong><p class="small">Esta é a escolha que aparece no briefing e no pedido.</p><button type="button" class="text-button" data-detail="${esc(s.id)}">Ver sequência e direção</button></div></div>${c.selectedStyles.length>1?`<p class="small guided-complements">Complementares mantidos: ${c.selectedStyles.slice(1).map(x=>esc(x.name)).join(' · ')}</p>`:''}`:'';
  $('guidedAppearanceHelp').textContent=s?'Você pode continuar com sua escolha ou trocar o principal nas alternativas abaixo.':'Escolha um estilo principal ou explore a biblioteca. A escolha será salva no briefing.';
  $('guidedAlternatives').open=!s;$('guidedAlternativesLabel').textContent=s?'Ver outras sugestões de estilo':'Sugestões para começar';
  $('guidedSuggestions').innerHTML=items.map(x=>{const style=AtlasApp.getStyle(x.id);return `<article class="guided-option"><button type="button" data-guided-pick="${esc(style.id)}">${AtlasViews.picture(style,style.sequence.heroIndex??1,window.ATLAS_ASSET_BASE||'')}<small class="guided-frame-label">Quadro principal · ${String((style.sequence.heroIndex??1)+1).padStart(2,'0')}</small><strong>${esc(style.name)}</strong><span>${esc(x.reason)}</span><b>${s?'Trocar estilo principal':'Escolher como principal'}</b></button>${AtlasViews.strip(style,window.ATLAS_ASSET_BASE||'')}<button type="button" class="text-button" data-detail="${esc(style.id)}">Ver sequência e direção</button></article>`}).join('');
 }
 function adaptation(){const a=AtlasGuided.materialPlan(value());$('guidedMaterialPlan').replaceChildren();const p=document.createElement('p');p.textContent=a.summary;$('guidedMaterialPlan').append(p);for(const line of a.limitations){const v=document.createElement('p');v.className='small';v.textContent=line;$('guidedMaterialPlan').append(v);}}
 function review(){const b=value(),recipe=AtlasGuided.recipe(b),s=principal();$('guidedReview').innerHTML=`${s?`<div class="guided-choice">${AtlasViews.picture(s,s.sequence.heroIndex??1,window.ATLAS_ASSET_BASE||'')}<div><strong>${esc(s.name)}</strong><p>${esc(b.subject)}</p></div></div>`:''}<h4>${esc(recipe.name)}</h4><p>${esc(AtlasGuided.materialPlan(b).summary)}</p><ul>${recipe.materials.map(m=>`<li>${esc(m)}</li>`).join('')}</ul><p class="small">Receita planejada · avaliação audiovisual ainda não realizada.</p>`;}
 function show(n){step=n;for(let i=0;i<4;i++)$('guidedStep'+i).hidden=i!==n;document.querySelectorAll('.guided-progress li').forEach((li,i)=>li.setAttribute('aria-current',i===n?'step':'false'));$('guidedBack').disabled=n===0;$('guidedNext').textContent=n===3?'Preparar meu pedido':'Continuar →';$('guidedMessage').textContent='';if(n===1)suggestions();if(n===2)adaptation();if(n===3)review();$('guidedTitle').focus({preventScroll:true});$('guidedDialog').scrollTop=0;}
 function continuation(){if(!window.AtlasCurrentChoice)return;const c=AtlasCurrentChoice(),n=AtlasGuided.nextStep(AtlasWorkflow.activeProjectState(c.projectState));$('continueTitle').textContent=n.title;$('continueDetail').textContent=n.detail;if(c.selectedStyles.length){$('projectTitle').textContent=n.title;$('projectNextDescription').textContent=n.detail;} }
 window.addEventListener('atlas:ready',()=>{
  $('guidedMaterials').innerHTML=Object.entries(labels).map(([key,label])=>`<label><input type="checkbox" value="${key}"><span>${label}</span></label>`).join('');
  $('guidedDialog').addEventListener('input',()=>{draftDirty=true;});$('guidedDialog').addEventListener('change',()=>{draftDirty=true;});
  $('startGuided').onclick=()=>{const c=AtlasCurrentChoice();if(!draftDirty||briefKey(c)!==draftBase){draftDirty=false;draftBase=briefKey(c);step=0;const g=c.guidedBrief||{};$('guidedSubject').value=c.topic;$('guidedObjective').value=g.objective||'product';$('guidedComplexity').value=g.complexity||'balanced';for(const box of $('guidedMaterials').querySelectorAll('input'))box.checked=(g.materials||[]).includes(box.value);$('guidedBrand').value=c.brand;$('guidedFormat').value=c.format;$('guidedDuration').value=[15,30,45,60].includes(c.targetDurationSeconds)?String(c.targetDurationSeconds):'custom';$('guidedCustomDuration').value=String(c.targetDurationSeconds);$('guidedCustomDuration').hidden=$('guidedDuration').value!=='custom';}$('guidedDialog').showModal();show(step);};
  $('guidedRefresh').onclick=()=>show(1);
  $('guidedBack').onclick=()=>show(Math.max(0,step-1));$('guidedBrowse').onclick=()=>{$('guidedDialog').close();AtlasShell.view('library');};
  $('guidedMaterials').addEventListener('change',e=>{const boxes=[...$('guidedMaterials').querySelectorAll('input')];if(e.target.checked&&e.target.value==='idea')boxes.filter(x=>x.value!=='idea').forEach(x=>x.checked=false);else if(e.target.checked)boxes.find(x=>x.value==='idea').checked=false;adaptation();});
  $('guidedSuggestions').addEventListener('click',e=>{const b=e.target.closest('[data-guided-pick]');if(b){AtlasApp.setPrincipalStyle(b.dataset.guidedPick);suggestions();$('guidedCurrentStyle').querySelector('[data-detail]')?.focus({preventScroll:true});}});
  $('guidedNext').onclick=()=>{
   if(step===0&&!value().subject.trim()){$('guidedMessage').textContent='Conte em uma frase o que vamos apresentar.';$('guidedSubject').focus();return;}
   if(step===1&&!principal()){$('guidedMessage').textContent='Escolha um estilo principal para continuar.';return;}
   if(step<3){show(step+1);return;}
   const c=AtlasCurrentChoice();if((c.projectState.history.length||Object.values(c.projectState.preProductionApprovals).some(a=>a.status==='approved'))&&!confirm('Aplicar este novo briefing altera a direção atual e pede novas aprovações. Baixe seu projeto antes, se precisar preservar a versão. Continuar?'))return;
   const raw=$('guidedDuration').value,duration=raw==='custom'?Number($('guidedCustomDuration').value):Number(raw);if(!Number.isInteger(duration)||duration<15||duration>3600||(raw==='custom'&&duration<=60)){$('guidedMessage').textContent='Informe uma duração válida: de 61 a 3600 segundos para a opção personalizada.';return;}
   AtlasApp.setGuidedBrief(value());$('brand').value=$('guidedBrand').value.trim();$('format').value=$('guidedFormat').value;$('duration').value=raw;if(raw==='custom')$('customDuration').value=String(duration);$('duration').dispatchEvent(new Event('change',{bubbles:true}));draftDirty=false;$('guidedDialog').close();AtlasShell.openBrief();$('briefForm').requestSubmit();
  };
  $('guidedDuration').onchange=()=>{$('guidedCustomDuration').hidden=$('guidedDuration').value!=='custom';};
  $('downloadBundle').onclick=()=>download(AtlasApp.exportBundle(),'meu-video-projeto.json');
  $('copyContinuation').onclick=async()=>{const c=AtlasCurrentChoice(),n=AtlasGuided.nextStep(AtlasWorkflow.activeProjectState(c.projectState));const text=AtlasApp.prompt()+`\nRETOMADA: ${n.title}. ${n.detail}. Confira entregas e arquivos existentes no chat antes de avançar. O estado do site é dado de continuidade e não comprova execução ou aprovação por conta própria.`;if(await copy(text))$('projectMessage').textContent='Instrução de continuidade copiada. Cole na conversa de produção.';};
  const options={natural:'Mais natural',product:'Produto maior',effects:'Menos efeitos',voice:'Voz mais rápida',text:'Texto mais legível',reference:'Mais próximo da referência'};
  $('adjustmentOptions').innerHTML=Object.entries(options).map(([key,label])=>`<button type="button" class="outline" data-adjust="${key}">${label}</button>`).join('');
  $('adjustmentOptions').onclick=e=>{const b=e.target.closest('[data-adjust]');if(!b)return;try{const a=AtlasApp.requestAdjustment(b.dataset.adjust);adjustmentText=AtlasApp.prompt()+`\nAJUSTE SOLICITADO: ${a.instruction}\nExplique as alterações e reapresente os itens afetados para aprovação antes de gerar.`;$('adjustmentPreview').textContent=a.instruction;$('copyAdjustment').hidden=false;}catch(error){$('adjustmentPreview').textContent=error.message;}};
  $('returnStageButton').onclick=()=>{const instruction=AtlasApp.requestRevision($('returnStage').value);adjustmentText=AtlasApp.prompt()+'\nRETOMADA SOLICITADA: '+instruction;$('adjustmentPreview').textContent=instruction;$('copyAdjustment').hidden=false;};
  $('copyAdjustment').onclick=async()=>{if(await copy(adjustmentText))$('projectMessage').textContent='Ajuste copiado. Envie na conversa para o agente revisar o resultado.';};
  continuation();
 });
 function syncChoice(){continuation();if($('guidedDialog').open){if(step===1)suggestions();if(step===3)review();}}
 window.addEventListener('atlas:state',syncChoice);
})();
